    internal static RoomEnemyNativeWords Of(EnemyDefinitionId id) => Words[id];

    /// <summary>A slot's native header words.</summary>
    extension(RoomEnemySlot slot)
    {
        /// <summary>The native words of the header the slot's definition identity names.</summary>
        internal RoomEnemyNativeWords NativeHeader => Words[slot.DefinitionId];
    }
}

/// <summary>The bank-qualified words of one compiled enemy header that the decoded definition replaces.</summary>
internal readonly record struct RoomEnemyNativeWords(byte Bank, ushort PalettePointer, ushort InitializationAiPointer,
    ushort MainAiPointer, ushort HurtAiPointer, ushort FrozenAiPointer, ushort TimeFrozenAiPointer,
    ushort PowerBombReactionPointer, ushort TouchAiPointer, ushort ShotAiPointer, ushort InitialSpritemapPointer,
    ushort NamePointer);
